function loadPdfLibrary(){if(window.pdfjsLib)return Promise.resolve(window.pdfjsLib);if(pdfLibraryPromise)return pdfLibraryPromise;pdfLibraryPromise=new Promise((resolve,reject)=>{const s=document.createElement('script');s.src=PDFJS_URL;s.onload=()=>{if(!window.pdfjsLib)return reject(new Error('PDF reader did not load'));window.pdfjsLib.GlobalWorkerOptions.workerSrc='https://cdnjs.cloudflare.com/ajax/libs/pdf.js/3.11.174/pdf.worker.min.js';resolve(window.pdfjsLib)};s.onerror=()=>reject(new Error('PDF reader requires an internet connection on first use. Your document stays on this device.'));document.head.appendChild(s)}).catch(e=>{pdfLibraryPromise=null;throw e});return pdfLibraryPromise}
