async function extractPaycheckPdf(file){const lib=await loadPdfLibrary(),bytes=new Uint8Array(await file.arrayBuffer()),doc=await lib.getDocument({data:bytes,useSystemFonts:true}).promise;try{if(doc.numPages!==1)throw Error('Expected a one-page City of Phoenix paystub.');const page=await doc.getPage(1),content=await page.getTextContent(),items=content.items.filter(x=>x.str?.trim()).map(x=>({s:x.str.trim(),x:x.transform[4],y:x.transform[5]}));items.sort((a,b)=>b.y-a.y||a.x-b.x);const lines=[];for(const item of items){let row=lines.find(r=>Math.abs(r.y-item.y)<3);if(!row){row={y:item.y,items:[]};lines.push(row)}row.items.push(item)}const text=lines.sort((a,b)=>b.y-a.y).map(r=>r.items.sort((a,b)=>a.x-b.x).map(v=>v.s).join('    ')).join('\n');return parsePhoenixPaycheck(text)}finally{doc.destroy()}}
