  modal(`<h2>Recurring Payments & Logos</h2><p class="note">Calendar reminders only. No expenses or debt payments are recorded automatically.</p>${rows||'<p class="note">No recurring payments yet.</p>'}<button class="primary" id="newRecurring" style="width:100%;margin-top:14px">＋ Add Recurring Payment</button><button class="secondary" id="doneRecurring" style="width:100%;margin-top:10px">Done</button>`);
  document.querySelectorAll('[data-edit-bill]').forEach(b=>b.onclick=()=>recurringEditor(Number(b.dataset.editBill)));
  document.getElementById('newRecurring').onclick=()=>recurringEditor(-1);
