 document.querySelectorAll('[data-calendar-bill]').forEach(el=>el.onclick=()=>{const b=(data.bills||[]).find(x=>String(x.id)===el.dataset.calendarBill);if(!b)return;const matched=calendarBillMatches(b,date);if(matched.length)expense(matched[0]);else expense(null,b.category||'Subscriptions',b.name,{amount:b.amount,date,note:b.name})});
 document.querySelectorAll('[data-calendar-debt]').forEach(el=>el.onclick=()=>{const n=el.dataset.calendarDebt;const recorded=(data.financeLog||[]).filter(x=>x.type==='debt'&&x.name===n&&x.date?.slice(0,7)===date.slice(0,7));if(recorded.length){modal(`<h2>${esc(n)} payments</h2>${recorded.map(x=>`<div class="row"><span>${esc(x.date)}</span><b>${fmt(x.paymentAmount??x.amount)}</b></div>`).join('')}<p class="note">Edit payments from Log.</p><button class="secondary" id="calBack">Back</button>`);document.getElementById('calBack').onclick=()=>calendarDayDetails(date)}else{recordDebtPayment(n);const field=document.getElementById('debtPaymentDate');if(field)field.value=date}});
 document.querySelectorAll('[data-calendar-pay]').forEach(el=>{el.onclick=()=>{const existing=data.paychecks.find(p=>p.date===date);paycheckEditor(existing?.id);const field=document.getElementById('pd');if(field)field.value=date}});
 document.querySelectorAll('[data-calendar-tx]').forEach(el=>el.onclick=()=>{const t=data.transactions.find(t=>t.id===el.dataset.calendarTx);if(t)expense(t)});
